namespace Crateside.Core.Queue;

/// <summary>
/// Whether a queued video is likely to yield a YouTube Premium audio format when downloaded.
/// </summary>
public enum PremiumOutlook
{
    /// <summary>Nothing can be said — the item carries no description to judge by.</summary>
    Unknown,

    /// <summary>An auto-generated YouTube Music art track.</summary>
    ArtTrack,

    /// <summary>
    /// An ordinary video upload. May still carry premium audio, but a better URL for the
    /// same song often exists.
    /// </summary>
    VideoUpload,
}

/// <summary>
/// Reads the premium outlook from the auto-generated-by-YouTube marker in the video
/// description.
/// </summary>
/// <remarks>
/// The marker's presence is precise, but its absence predicts nothing — 42% of videos without it
/// were still premium audio, which is why nothing is said to the user off this and the one live
/// use is routing an art track to its <c>music.youtube.com</c> URL. What a download actually got
/// is <see cref="Orchestration.Acquisition"/> (ADR 0016). See <c>docs/premium-outlook.md</c>.
/// </remarks>
public static class PremiumOutlookReader
{
    private const string AutoGeneratedMarker = "Auto-generated by YouTube";

    public static PremiumOutlook FromDescription(string? description) =>
        description?.Trim() switch
        {
            not { Length: > 0 } => PremiumOutlook.Unknown,
            { } text when text.Contains(AutoGeneratedMarker, StringComparison.Ordinal) =>
                PremiumOutlook.ArtTrack,
            _ => PremiumOutlook.VideoUpload,
        };
}
